// Interroge la page de résultats de recherche Airbnb (HTML public, sans clé API)
// sur 3 fenêtres de dates (base ± flex_days) et N pages, avec filtres natifs
// Airbnb (logement entier + type Maison + amenité Piscine).
// Filtre ensuite strictement sur le budget TOTAL (le filtre Airbnb est par nuit).
const criteria = $input.first().json;
const location = encodeURIComponent(criteria.location_slug);
const baseCheckIn = criteria.check_in;
const baseCheckOut = criteria.check_out;
const adults = criteria.guests;
const priceMinTotal = Number(criteria.price_min_total);
const priceMaxTotal = Number(criteria.price_max_total);
const flexDays = Number(criteria.flex_days) || 0;
const pages = Number(criteria.pages) || 1;
const propertyTypeId = criteria.property_type_id || 1;
const poolAmenityId = criteria.pool_amenity_id || 7;
const pageSize = 18;

function addDays(dateStr, days) {
  const d = new Date(dateStr + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

const nights = Math.max(1, Math.round((new Date(baseCheckOut) - new Date(baseCheckIn)) / 86400000));
const priceMinNight = Math.max(0, Math.floor(priceMinTotal / nights));
const priceMaxNight = Math.ceil(priceMaxTotal / nights);

const offsets = flexDays > 0 ? [-flexDays, 0, flexDays] : [0];
const byListing = new Map();

for (const offset of offsets) {
  const checkIn = addDays(baseCheckIn, offset);
  const checkOut = addDays(baseCheckOut, offset);

  for (let page = 0; page < pages; page++) {
    const itemsOffset = page * pageSize;
    const url = `https://www.airbnb.com/s/${location}/homes?checkin=${checkIn}&checkout=${checkOut}&adults=${adults}&price_min=${priceMinNight}&price_max=${priceMaxNight}&room_types%5B%5D=Entire%20home%2Fapt&l2_property_type_ids%5B%5D=${propertyTypeId}&amenities%5B%5D=${poolAmenityId}&items_offset=${itemsOffset}`;

    let html;
    try {
      html = await this.helpers.httpRequest({
        method: 'GET',
        url,
        headers: {
          'Accept-Language': 'fr-FR,fr;q=0.9',
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36'
        }
      });
    } catch (e) {
      continue;
    }

    const match = html.match(/<script[^>]*data-deferred-state[^>]*>([\s\S]*?)<\/script>/);
    if (!match) continue;

    let data;
    try {
      data = JSON.parse(match[1]);
    } catch (e) {
      continue;
    }

    const results = data?.niobeClientData?.[0]?.[1]?.data?.presentation?.staysSearch?.results?.searchResults || [];

    for (const r of results) {
      const b64 = r.demandStayListing?.id;
      if (!b64) continue;

      let numericId;
      try {
        numericId = Buffer.from(b64, 'base64').toString('utf8').replace('DemandStayListing:', '');
      } catch (e) {
        continue;
      }
      if (!numericId) continue;

      const priceFormatted = r.structuredDisplayPrice?.primaryLine?.price || null;
      const priceNumeric = priceFormatted ? Number(priceFormatted.replace(/[^0-9]/g, '')) : null;

      // Garde-fou : le filtre URL est par nuit (approximatif), on impose ici le budget TOTAL exact
      if (priceNumeric === null || priceNumeric < priceMinTotal || priceNumeric > priceMaxTotal) continue;

      const existing = byListing.get(numericId);
      if (!existing || priceNumeric < existing.price_eur) {
        const name = r.nameLocalized?.localizedStringWithTranslationPreference || r.title || 'Sans titre';
        byListing.set(numericId, {
          listing_id: numericId,
          name,
          price_eur: priceNumeric,
          price_formatted: priceFormatted,
          url: `https://www.airbnb.com/rooms/${numericId}`,
          check_in: checkIn,
          check_out: checkOut
        });
      }
    }

    // Petite pause entre chaque appel pour rester discret vis-à-vis d'Airbnb
    await new Promise((res) => setTimeout(res, 1500));
  }
}

return Array.from(byListing.values()).map((v) => ({ json: v }));

// Compare les annonces trouvées à celles déjà notifiées (onglet Seen),
// ne garde que les nouvelles, et prépare le texte du message Slack.
const seenRows = $input.all()
  .map((i) => i.json.listing_id)
  .filter((v) => v !== undefined && v !== null && v !== '')
  .map((v) => String(v));
const seenSet = new Set(seenRows);

const allFound = $('Chercher Nouvelles Annonces').all();
const newOnes = allFound.filter((item) => !seenSet.has(String(item.json.listing_id)));

return newOnes.map((item) => {
  const d = item.json;
  const slackMessage = [
    `🆕 *${d.name}*`,
    `💰 ${d.price_formatted}`,
    `📆 ${d.check_in} → ${d.check_out}`,
    `🔗 ${d.url}`
  ].join('\n');

  return {
    json: {
      ...d,
      first_seen: new Date().toISOString(),
      slack_message: slackMessage
    }
  };
});
